package com.bookflow.businesses.members.api;
import com.bookflow.businesses.application.CurrentBusinessUserUnavailableException; import com.bookflow.businesses.members.application.MemberService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import org.springframework.context.annotation.Profile; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.util.*;
@RestController @Profile("!test") @RequestMapping("/api/v1/businesses/{businessId}/members") @Tag(name="Business Members") @SecurityRequirement(name="bearerAuth") public class BusinessMemberController {private final MemberService s;public BusinessMemberController(MemberService s){this.s=s;}
 @GetMapping @Operation(summary="Danh sách member") public List<MemberResponse> list(@PathVariable UUID businessId,Authentication a){return s.list(user(a),businessId);} @PostMapping @Operation(summary="Mời user đã có tài khoản") public ResponseEntity<MemberResponse> invite(@PathVariable UUID businessId,@RequestBody CreateMemberRequest r,Authentication a){MemberResponse x=s.invite(user(a),businessId,r);return ResponseEntity.status(201).header(HttpHeaders.LOCATION, URI.create("/api/v1/businesses/"+businessId+"/members/"+x.id()).toString()).body(x);} @PatchMapping("/{memberId}/role") @Operation(summary="Đổi role member") public MemberResponse role(@PathVariable UUID businessId,@PathVariable UUID memberId,@RequestBody UpdateMemberRoleRequest r,Authentication a){return s.role(user(a),businessId,memberId,r);} @DeleteMapping("/{memberId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void revoke(@PathVariable UUID businessId,@PathVariable UUID memberId,Authentication a){s.revoke(user(a),businessId,memberId);} @PutMapping("/{memberId}/employee/{employeeId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void link(@PathVariable UUID businessId,@PathVariable UUID memberId,@PathVariable UUID employeeId,Authentication a){s.link(user(a),businessId,memberId,employeeId);} @DeleteMapping("/{memberId}/employee") @ResponseStatus(HttpStatus.NO_CONTENT) public void unlink(@PathVariable UUID businessId,@PathVariable UUID memberId,Authentication a){s.unlink(user(a),businessId,memberId);} private UUID user(Authentication a){try{return UUID.fromString(a.getName());}catch(Exception e){throw new CurrentBusinessUserUnavailableException();}}}
